import numpy as np
from scipy.optimize import minimize
import os

N = 26

def construct_packing() -> tuple:
    try:
        base_centers = np.loadtxt('storage/episteme/sota_base_centers.txt')
        base_radii = np.loadtxt('storage/episteme/sota_base_radii.txt')
    except Exception:
        return np.array([[0.5, 0.5]] * 26), np.array([0.05] * 26)

    # --- Heuristic: Get existing contacts ---
    def get_contacts(centers, radii):
        contacts = []
        for i in range(N):
            for j in range(i + 1, N):
                dist = np.linalg.norm(centers[i] - centers[j])
                if abs(dist - (radii[i] + radii[j])) < 1e-6:
                    contacts.append((i, j))
        return contacts

    base_contacts = get_contacts(base_centers, base_radii)
    # Let's test a few promising contacts from the middle of the list
    pairs_to_squeeze = base_contacts[5:10] 

    # --- Helper functions ---
    def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
    def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]
    def objective(z): return -np.sum(z[N*2:])
    def ineq_boundary(z):
        c, r = z_to_cr(z)
        return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])
    def ineq_nonoverlap(z):
        c, r = z_to_cr(z)
        diff = c[:, None, :] - c[None, :, :]; dist = np.sqrt(np.sum(diff**2, axis=-1))
        iu = np.triu_indices(N, 1); return dist[iu] - (r[iu[0]] + r[iu[1]])
    def _ensure_validity(c, r):
        for _ in range(10):
            v = 0
            for i in range(N):
                for j in range(i + 1, N):
                    dist = np.linalg.norm(c[i] - c[j]); rad_sum = r[i] + r[j]
                    if dist < rad_sum: v+=1; scale = (dist/rad_sum)*(1.0-1e-9); r[i]*=scale; r[j]*=scale
            if v == 0: break
        return c, np.maximum(r, 0)

    # --- Main Loop ---
    overall_best_score = -np.inf
    overall_best_centers, overall_best_radii = None, None

    for target_pair in pairs_to_squeeze:
        # --- Stage 1: Squeezing ---
        squeezed_centers = np.copy(base_centers)
        i_sq, j_sq = target_pair
        dist_vec = squeezed_centers[i_sq] - squeezed_centers[j_sq]
        dist = np.linalg.norm(dist_vec)

        if dist > 1e-9:
            grad_ci = dist_vec / dist
            squeeze_amount = 1e-4 # A small, constant squeeze force
            squeezed_centers[i_sq] += grad_ci * squeeze_amount
            squeezed_centers[j_sq] -= grad_ci * squeeze_amount

        # Use original radii for refinement stage
        squeezed_radii = np.copy(base_radii)

        # --- Stage 2: Refinement ---
        run_best_score = -np.inf
        run_best_centers, run_best_radii = None, None
        jitter_amplitudes = [1e-4, 5e-4, 1e-3, 2e-3] # Reduced search for efficiency
        restarts_per_amplitude = 4
        bounds = [(0,1)]*N*2 + [(1e-6, 0.5)]*N
        constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]

        for amp in jitter_amplitudes:
            for i in range(restarts_per_amplitude):
                np.random.seed(int(amp * 1e6) + i + 500)
                jitter = np.random.uniform(-amp, amp, size=squeezed_centers.shape)
                perturbed_centers = np.clip(squeezed_centers + jitter, 1e-6, 1 - 1e-6)
                initial_z = cr_to_z(perturbed_centers, squeezed_radii)

                res = minimize(objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 500, 'ftol': 1e-9})

                if res.success:
                    c_res, r_res = z_to_cr(res.x)
                    c_final, r_final = _ensure_validity(c_res, r_res)
                    final_score = np.sum(r_final)
                    if final_score > run_best_score:
                        run_best_score = final_score; run_best_centers, run_best_radii = c_final, r_final

        if run_best_score > overall_best_score:
            overall_best_score = run_best_score
            overall_best_centers, overall_best_radii = run_best_centers, run_best_radii

    if overall_best_centers is None:
        return base_centers, base_radii

    return overall_best_centers, overall_best_radii
